import React, { useState } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const handleSubmit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id:Date.now(), user_text:text, ...ai, date:new Date().toISOString() };
      addThought(entry); setResult(entry);
    } catch { setError('Kunde inte analysera just nu. Försök igen.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={()=>{setResult(null);setText('');}} setPage={setPage}/>;

  return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <Background mood="default" />

      <div style={{ position:'relative', zIndex:1, padding:'32px 22px 0', maxWidth:480, margin:'0 auto' }}>

        {/* Hero — sphere + heading side by side feel */}
        <div style={{ display:'flex', flexDirection:'column', alignItems:'center', marginBottom:28, animation:'fadeIn .9s ease both' }}>
          <MeshSphere size={280} speed={0.5} distort={0.45} />

          {streak > 0 && (
            <div style={{ marginTop:-12, background:'rgba(255,255,255,0.8)', backdropFilter:'blur(12px)', border:'1px solid rgba(255,255,255,0.9)', borderRadius:100, padding:'5px 16px', fontSize:12, fontWeight:600, color:'#1c1917', boxShadow:'0 2px 12px rgba(0,0,0,0.08)' }}>
              🔥 {streak} dagar i rad
            </div>
          )}
        </div>

        {/* Heading — warm, inviting, not aggressive */}
        <div style={{ marginBottom:28, animation:'fadeUp .8s .1s both' }}>
          <p style={{ fontSize:12, color:'rgba(28,25,23,0.45)', fontWeight:500, letterSpacing:'0.04em', marginBottom:8, textTransform:'uppercase' }}>KBT-baserad tankeanalys</p>
          <h1 style={{ fontSize:'clamp(32px,8vw,52px)', fontWeight:700, letterSpacing:'-0.04em', lineHeight:1.05, color:'#1c1917' }}>
            Vad är det som<br/>
            <span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.5)' }}>snurrar just nu?</span>
          </h1>
        </div>

        {/* Input card — warm white, rounded */}
        <div style={{ background:'rgba(255,255,255,0.75)', backdropFilter:'blur(20px) saturate(1.5)', borderRadius:24, border:'1px solid rgba(255,255,255,0.95)', boxShadow:'0 4px 24px rgba(0,0,0,0.06), 0 1px 0 rgba(255,255,255,1) inset', marginBottom:12, overflow:'hidden', animation:'fadeUp .8s .2s both' }}>
          <div style={{ padding:'18px 20px 10px' }}>
            <textarea value={text} onChange={e=>setText(e.target.value)} maxLength={1000}
              placeholder="Skriv fritt — inga rätta svar..."
              style={{ width:'100%', minHeight:110, background:'transparent', border:'none', color:'#1c1917', fontSize:16, fontWeight:300, lineHeight:1.8, resize:'none', outline:'none', placeholder:'rgba(28,25,23,0.3)' }}
            />
          </div>
          <div style={{ padding:'10px 20px 14px', display:'flex', justifyContent:'space-between', alignItems:'center', borderTop:'1px solid rgba(0,0,0,0.05)' }}>
            <span style={{ fontSize:12, color:'rgba(28,25,23,0.3)', fontWeight:400 }}>{text.length} / 1000</span>
            <button onClick={handleSubmit} disabled={!text.trim()||loading}
              style={{ padding:'10px 22px', borderRadius:100, background: text.trim()&&!loading ? '#1c1917' : 'rgba(0,0,0,0.08)', color: text.trim()&&!loading ? '#f0ece6' : 'rgba(28,25,23,0.3)', fontSize:13, fontWeight:600, transition:'all .25s', border:'none', boxShadow: text.trim()&&!loading ? '0 4px 16px rgba(0,0,0,0.2)' : 'none' }}>
              {loading ? <span style={{ display:'flex',alignItems:'center',gap:8 }}><span style={{ width:10,height:10,border:'2px solid rgba(240,236,230,0.3)',borderTopColor:'#f0ece6',borderRadius:'50%',display:'inline-block',animation:'spin .7s linear infinite' }}/>Analyserar</span> : 'Analysera →'}
            </button>
          </div>
          {error && <p style={{ padding:'0 20px 14px', fontSize:13, color:'rgba(200,60,60,0.8)' }}>{error}</p>}
        </div>

        {/* Quick links — gradient cards like Light app */}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, animation:'fadeUp .8s .3s both' }}>
          <GradCard
            onClick={()=>setPage('checkin')}
            gradient="linear-gradient(135deg, rgba(148,172,182,0.88) 0%, rgba(158,180,182,0.82) 100%)"
            label="Check-in" sub="Hur mår du idag?"
          />
          <GradCard
            onClick={()=>setPage('breathing')}
            gradient="linear-gradient(135deg, rgba(145,170,178,0.88) 0%, rgba(155,178,180,0.82) 100%)"
            label="Andning" sub="4-7-8 tekniken"
          />
        </div>
      </div>
    </div>
  );
}

function GradCard({ onClick, gradient, label, sub }) {
  return (
    <button onClick={onClick} style={{ padding:'18px 16px', borderRadius:20, background:gradient, border:'1px solid rgba(255,255,255,0.7)', boxShadow:'0 4px 16px rgba(0,0,0,0.08), 0 1px 0 rgba(255,255,255,0.8) inset', textAlign:'left', transition:'transform .2s, box-shadow .2s' }}
      onMouseEnter={e=>{e.currentTarget.style.transform='translateY(-2px)';e.currentTarget.style.boxShadow='0 8px 24px rgba(0,0,0,0.12), 0 1px 0 rgba(255,255,255,0.8) inset'}}
      onMouseLeave={e=>{e.currentTarget.style.transform='none';e.currentTarget.style.boxShadow='0 4px 16px rgba(0,0,0,0.08), 0 1px 0 rgba(255,255,255,0.8) inset'}}>
      <div style={{ fontSize:14, fontWeight:600, color:'rgba(28,25,23,0.85)', marginBottom:3, letterSpacing:'-0.01em' }}>{label}</div>
      <div style={{ fontSize:11, color:'rgba(28,25,23,0.5)', fontWeight:400 }}>{sub}</div>
    </button>
  );
}

