        <div style={{ background:'rgba(255,255,255,0.6)', borderRadius:18, padding:'14px 18px', marginBottom:20, backdropFilter:'blur(16px)', border:'1px solid rgba(255,255,255,0.85)' }}>
          <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em', marginBottom:7 }}>Du skrev</p>
          <p style={{ fontSize:14, color:'rgba(28,25,23,0.6)', fontStyle:'italic', lineHeight:1.75 }}>"{text.slice(0,140)}{text.length>140?'...':''}"</p>
