          <h2 style={{ fontSize:'clamp(26px,7vw,42px)', fontWeight:700, letterSpacing:'-0.04em', lineHeight:1, color:'#1c1917' }}>{result.trap_label}</h2>
        </div>

        {/* Cards */}
        {[
          { label:'Vad händer', body:result.description, grad:'linear-gradient(135deg, rgba(152,175,185,0.72) 0%, rgba(162,182,185,0.65) 100%)' },
          { label:'Omramning', body:result.reframe,      grad:'linear-gradient(135deg, rgba(145,172,182,0.72) 0%, rgba(155,180,182,0.65) 100%)' },
          { label:'Övning',    body:result.exercise_text, grad:'linear-gradient(135deg, rgba(148,175,172,0.72) 0%, rgba(158,182,175,0.65) 100%)' },
        ].map(({ label, body, grad }) => (
          <div key={label} style={{ background:grad, backdropFilter:'blur(16px)', borderRadius:20, padding:'16px 18px', marginBottom:10, border:'1px solid rgba(255,255,255,0.75)', boxShadow:'0 2px 12px rgba(0,0,0,0.06)' }}>
            <p style={{ fontSize:11, color:'rgba(28,25,23,0.5)', fontWeight:600, textTransform:'uppercase', letterSpacing:'0.06em', marginBottom:8 }}>{label}</p>
            <p style={{ fontSize:14, color:'rgba(28,25,23,0.8)', lineHeight:1.85, fontWeight:300 }}>{body}</p>
          </div>
        ))}

        <div style={{ display:'flex', gap:10, marginTop:8 }}>
          <button onClick={()=>setPage('breathing')} style={{ flex:1, padding:'13px', borderRadius:16, background:'rgba(255,255,255,0.65)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.65)', fontSize:13, fontWeight:500, backdropFilter:'blur(12px)', transition:'all .2s' }}>
            🫁 Andningsövning
          </button>
          <button onClick={onBack} style={{ padding:'13px 18px', fontSize:13, color:'rgba(28,25,23,0.4)', fontWeight:400 }}>
            ← Tillbaka
          </button>
        </div>
      </div>
    </div>
  );
}
